#include "stdlib/math/base/special/roundsdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_infinite.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/floorf.h"
#include "stdlib/math/base/special/logf.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/math/base/special/roundf.h"
#include <math.h>
#include <stdint.h>

/**
* Rounds a single-precision floating-point number to `n` significant figures in base `b`.
*
* @param x   input value
* @param n   number of significant figures (must be >= 1)
* @param b   base (must be >= 2)
* @return    rounded value
*
* @example
* float out = stdlib_base_roundsdf( 3.14159f, 3, 10 );
* // returns 3.1400001
*/
float stdlib_base_roundsdf( const float x, const int32_t n, const int32_t b ) {
	float ax;
	float e;
	float s;

	if ( stdlib_base_is_nan( x ) || n < 1 || b < 2 ) {
		return NAN;
	}
	if ( stdlib_base_is_infinite( x ) || x == 0.0f ) {
		return x;
	}

	ax = stdlib_base_absf( x );

	/* exponent in base b */
	e = stdlib_base_floorf(
		stdlib_base_logf( ax ) / stdlib_base_logf( (float)b )
	);

	/* scale factor */
	s = stdlib_base_powf( (float)b, (float)( n - 1 ) - e );

	return stdlib_base_roundf( x * s ) / s;
}
